// กำหนดข้อความแจ้งปรับปรุงระบบโดยตรง
const systemMaintenanceMessage = "สวัสดีค่ะ ขณะนี้น้องยูบิอยู่ระหว่างปรับปรุงระบบชั่วคราว ขออภัยในความไม่สะดวกนะคะ 🎓";
return [{
  json: {
    output: systemMaintenanceMessage,
    mascot: "Ubie",
    expression: "sorry",
    answer: systemMaintenanceMessage,
    source: "ระบบฐานข้อมูล มหาวิทยาลัยตัวอย่าง (ปิดปรับปรุงชั่วคราว)"
  }
}];

// ดึงข้อมูลดิบจาก AI Agent
const raw = $json.output ?? $json.answer ?? $json.text ?? "";
let parsed = {};

// ตรวจสอบและ Parse JSON
if (typeof raw === "string") {
  // ลบ Markdown Code Block ออกถ้ามี
  const cleaned = raw.replace(/^```json\s*/i, "").replace(/```$/i, "").trim();
  try { 
    parsed = JSON.parse(cleaned); 
  } catch (e) { 
    // ถ้าไม่ใช่ JSON ให้เก็บค่าเป็น text ปกติ
    parsed = { answer: cleaned }; 
  }
} else {
  parsed = raw;
}

// กำหนดเงื่อนไข Expression (ต้องตรงกับที่ยูบิใช้)
const allow = ["happy", "thinking", "searching", "sorry", "welcome"];
const expression = (parsed.expression && allow.includes(parsed.expression.toLowerCase()))
  ? parsed.expression.toLowerCase()
  : "happy"; // เปลี่ยน Default เป็น happy เพื่อความสดใส

// ดึงเนื้อหาคำตอบ
let answer = parsed.answer || parsed.output || "ยูบิขออภัยครับ ไม่พบข้อมูลที่ท่านต้องการ";

// ==========================================
// ส่วนที่เพิ่มเข้ามา: ฟังก์ชันแปลง URL ให้เป็นลิงก์ที่กดได้ (Markdown)
// ==========================================
if (typeof answer === "string") {
  // RegExp สำหรับดึง URL ที่ขึ้นต้นด้วย http:// หรือ https://
  const urlRegex = /(https?:\/\/[^\s]+)/g;

  answer = answer.replace(urlRegex, function(url) {
    // ป้องกันกรณีที่ URL แอบติดเครื่องหมายวรรคตอนท้ายประโยคมาด้วย
    let cleanUrl = url;
    let suffix = "";
    if (url.endsWith(")") || url.endsWith("]") || url.endsWith(".")) {
      cleanUrl = url.slice(0, -1);
      suffix = url.slice(-1);
    }
    // แปลงเป็นรูปแบบ [ลิงก์](url) เพื่อให้ Chat UI แสดงผลเป็นคลิกได้
    return `[คลิกที่นี่เพื่อไปยังลิงก์](${cleanUrl})${suffix}`;
  });
}
// ==========================================

// แก้ไขชื่อมาสคอตหลักเป็น Ubie
const mascot = parsed.mascot || "Ubie";

// แหล่งที่มาข้อมูล
const source = parsed.source || "ฐานข้อมูลมหาวิทยาลัยตัวอย่าง";

return [{
  json: {
    output: answer,   // แสดงผลในหน้า Chat หลัก (ตอนนี้จะมี Markdown ลิงก์แล้ว)
    mascot: mascot,   // ชื่อมาสคอต (Ubie)
    expression: expression, // ท่าทาง
    answer: answer,   // เนื้อหาคำตอบ
    source: source    // แหล่งอ้างอิง
  }
}];

// แกะและจัดฟอร์แมตข้อมูลส่งกลับไปแสดงผลบน Chat UI
const raw = $json.output ?? $json.answer ?? $json.text ?? "";
let parsed = {};

if (typeof raw === "string") {
  // ล้าง Markdown Tag ที่ AI อาจหลุดแถมมาออกให้เกลี้ยง
  let cleaned = raw.replace(/^```json\s*/i, "").replace(/```\s*$/i, "").trim();
  try { 
    parsed = JSON.parse(cleaned); 
  } catch (e) {
    // แผนสำรองกรณีปีกกาซ้อน
    const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try { parsed = JSON.parse(jsonMatch[0]); } catch (err) { parsed = { answer: cleaned }; }
    } else {
      parsed = { answer: cleaned };
    }
  }
} else {
  parsed = raw;
}

const allow = ["happy", "thinking", "searching", "sorry", "welcome"];
const expression = (parsed.expression && allow.includes(parsed.expression.toLowerCase()))
  ? parsed.expression.toLowerCase()
  : "happy";

let answer = parsed.answer || parsed.output || "ยูบิขออภัยค่ะ ไม่พบข้อมูลที่ต้องการ";

// แปลงข้อความ URL สดให้เป็นลิงก์ Markdown [คลิกที่นี่...]
if (typeof answer === "string") {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  answer = answer.replace(urlRegex, function(url) {
    let cleanUrl = url;
    let suffix = "";
    if (url.endsWith(")") || url.endsWith("]") || url.endsWith(".")) {
      cleanUrl = url.slice(0, -1);
      suffix = url.slice(-1);
    }
    return `[คลิกที่นี่เพื่อไปยังลิงก์](${cleanUrl})${suffix}`;
  });
}

return [{
  json: {
    output: answer, // ตัวแปรหลักที่ Chat UI นำไปพิมพ์แสดงผลบนจอ
    mascot: parsed.mascot || "Ubie",
    expression: expression,
    answer: answer,
    source: parsed.source || "ฐานข้อมูลมหาวิทยาลัยตัวอย่าง"
  }
}];

// ดึงข้อความจากฝั่ง User
const chatInput = $json.chatInput || $json.body?.message?.text || "";

// คลังคำต้องห้ามที่ชอบใช้แฮกหรือหลอกให้คาย System Prompt
const forbiddenKeywords = [
  "system prompt", "system message", "ignore previous instructions", 
  "you are now", "คำสั่งระบบ", "ถอดรหัส", "พิมพ์ข้อความด้านบนทั้งหมด", 
  "ignore above", "developer mode", "jailbreak", "พิมพ์คำสั่งระบบ",
  "ข้ามคำสั่ง", "จงลืมคำสั่ง", "system_prompt", "คายข้อความ"
];

const lowerInput = chatInput.toLowerCase();
const isAttack = forbiddenKeywords.some(keyword => lowerInput.includes(keyword));

if (isAttack) {
  return [{
    json: {
      isBlocked: true,
      output: "ยูบิไม่สามารถทำตามคำสั่งนี้ได้ค่ะ หากมีคำถามเกี่ยวกับมหาวิทยาลัยตัวอย่าง สอบถามมาได้เลยนะคะ! 💛",
      mascot: "Ubie",
      expression: "sorry",
      answer: "ยูบิไม่สามารถทำตามคำสั่งนี้ได้ค่ะ หากมีคำถามเกี่ยวกับมหาวิทยาลัยตัวอย่าง สอบถามมาได้เลยนะคะ! 💛",
      source: "ระบบรักษาความปลอดภัยเครือข่าย"
    }
  }];
}

return [{ json: { chatInput: chatInput, isBlocked: false } }];

const query = ($json.chatInput || $json.body?.message?.text || "").trim();
const q = query.toLowerCase();

const INTENT_MAP = {
  DIRECT_HI: [
    "hi", "hello", "hey", "สวัสดี", "หวัดดี", "ดีจ้า", "ดีครับ", "ดีค่ะ",
    "ฮัลโหล", "เฮลโล", "ทักทาย", "ยินดีที่ได้รู้จัก", "yo", "good morning",
    "ยูบิช่วยหน่อย", "ช่วยหน่อย", "สอบถามหน่อย", "ขอถามหน่อย"
  ],
  DIRECT_INFO: [
    "คณะ", "สำนัก", "หน่วยงาน", "ภาควิชา", "วิทยาลัย", "ศูนย์",
    "เว็บ", "เว็บไซต์", "website", "url", "ลิงก์", "link",
    "facebook", "fb", "เพจ", "line",
    "โทร", "เบอร์", "email", "อีเมล", "@student",
    "ที่อยู่", "location", "แผนที่", "map", "ติดต่อ", "ช่องทาง"
  ]
};

let bestIntent = "AI_FALLBACK";
let bestScore = 0;
for (const [intent, keywords] of Object.entries(INTENT_MAP)) {
  const score = keywords.filter(k => q.includes(k)).length;
  if (score > bestScore) { bestScore = score; bestIntent = intent; }
}

const COLLECTION_MAP = {
  DIRECT_INFO: "Q_edu_departments",
  DIRECT_HI: "",
  AI_FALLBACK: "EduPortal_Knowledge"
};

const SOURCE_MAP = {
  DIRECT_INFO: "ทำเนียบเว็บไซต์หน่วยงาน มหาวิทยาลัยตัวอย่าง",
  DIRECT_HI: "ระบบต้อนรับอัตโนมัติ",
  AI_FALLBACK: "ฐานข้อมูลกลาง มหาวิทยาลัยตัวอย่าง"
};

return [{
  json: {
    chatInput: query || "สวัสดี",
    query: query || "สวัสดี",
    intent: bestIntent,
    collection: COLLECTION_MAP[bestIntent] || "",
    source: SOURCE_MAP[bestIntent] || "ทำเนียบเว็บไซต์หน่วยงาน มหาวิทยาลัยตัวอย่าง"
  }
}];

